using System.Security.Claims;
using CourseGuard.Backend.Controllers;
using CourseGuard.Backend.Data;
using CourseGuard.Backend.Models;
internal static class TeacherApi
{
    public static void MapTeacherApi(this RouteGroupBuilder api)
    {
        var group = api.MapGroup("/teacher").RequireAuthorization(p => p.RequireRole("TEACHER"));
        group.MapPost("/GetDashboardSummary", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetDashboardSummary(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/GetTeacherProfile", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetTeacherProfile(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/UpsertTeacherProfile", (UpsertTeacherProfileRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpsertTeacherProfile(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/GetCourses", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetCourses(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/CreateCourse", (CreateCourseRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).CreateCourse(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/UpdateCourse", (UpdateCourseRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpdateCourse(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/SubmitCourseForApproval", (SubmitCourseForApprovalRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).SubmitCourseForApproval(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId)));
        group.MapPost("/DeleteCourse", (DeleteCourseRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).DeleteCourse(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId)));
        group.MapPost("/GetLessons", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetLessons(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/CreateLesson", (CreateLessonRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).CreateLesson(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/UpdateLesson", (UpdateLessonRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpdateLesson(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/DeleteLesson", (DeleteLessonRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).DeleteLesson(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.lessonId)));
        group.MapPost("/GetAssignments", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetAssignments(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/CreateAssignment", (CreateAssignmentRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).CreateAssignment(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/UpdateAssignment", (UpdateAssignmentRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpdateAssignment(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/DeleteAssignment", (DeleteAssignmentRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).DeleteAssignment(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.assignmentId)));
        group.MapPost("/GetExams", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetExams(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/CreateExam", (CreateExamRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).CreateExam(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/UpdateExam", (UpdateExamRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpdateExam(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/ActivateExam", (ActivateExamRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).ActivateExam(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId)));
        group.MapPost("/CanActivateExam", (CanActivateExamRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).CanActivateExam(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId)));
        group.MapPost("/DeleteExam", (DeleteExamRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).DeleteExam(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId)));
        group.MapPost("/GetExamQuestions", (GetExamQuestionsRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetExamQuestions(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId)));
        group.MapPost("/GetExamStatus", (GetExamStatusRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetExamStatus(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId)));
        group.MapPost("/CreateExamQuestion", (CreateExamQuestionRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).CreateExamQuestion(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/UpdateExamQuestion", (UpdateExamQuestionRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpdateExamQuestion(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/DeleteExamQuestion", (DeleteExamQuestionRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).DeleteExamQuestion(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId, request.questionId)));
        group.MapPost("/GetPendingEnrollments", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetPendingEnrollments(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/GetEnrolledStudents", (GetEnrolledStudentsRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetEnrolledStudents(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId)));
        group.MapPost("/ApproveEnrollment", (ApproveEnrollmentRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).ApproveEnrollment(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId, request.studentId)));
        group.MapPost("/RejectEnrollment", (RejectEnrollmentRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).RejectEnrollment(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId, request.studentId)));
        group.MapPost("/GetResults", (GetResultsRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetResults(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId, request.examId)));
        group.MapPost("/UpdateScore", (UpdateScoreRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpdateScore(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/GetMaterials", (GetMaterialsRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetMaterials(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId)));
        group.MapPost("/CreateMaterial", (CreateMaterialRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).CreateMaterial(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/UpdateMaterial", (UpdateMaterialRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpdateMaterial(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/DeleteMaterial", (DeleteMaterialRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).DeleteMaterial(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.materialId)));
        group.MapPost("/GetSchedule", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetSchedule(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/GetAttendanceSummary", (GetAttendanceSummaryRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetAttendanceSummary(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.sessionId)));
        group.MapPost("/GetTeachingTasks", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetTeachingTasks(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/CreateScheduleItem", (CreateScheduleItemRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).CreateScheduleItem(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/UpdateScheduleItem", (UpdateScheduleItemRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).UpdateScheduleItem(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.input)));
        group.MapPost("/DeleteScheduleItem", (DeleteScheduleItemRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).DeleteScheduleItem(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.scheduleId)));
        group.MapPost("/UpdateSessionStatusAsync", async (UpdateSessionStatusAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db, ClassroomApi classroom) =>
        {
            int teacherId = int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!);
            bool updated = await new TeacherController(db).UpdateSessionStatusAsync(teacherId, request.sessionId, request.isOpened, request.meetingLink);
            if (updated && !request.isOpened) classroom.DisconnectStudents(request.sessionId, teacherId);
            return Results.Ok(updated);
        });
        group.MapPost("/GetOpenExamsCount", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetOpenExamsCount(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/GetActiveExamSessions", (ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetActiveExamSessions(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!))));
        group.MapPost("/GetStudentSubmissionsAsync", async (GetStudentSubmissionsAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(await new TeacherController(db).GetStudentSubmissionsAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId)));
        group.MapPost("/GetSubmissionContentAsync", async (GetSubmissionContentAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(await new TeacherController(db).GetSubmissionContentAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.submissionId)));
        group.MapPost("/UpdateGradeAsync", async (UpdateGradeAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(await new TeacherController(db).UpdateGradeAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.submissionId, request.score, request.feedback)));
        group.MapPost("/GetLessonFileContentAsync", async (GetLessonFileContentAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db, CancellationToken ct) =>
        {
            await using var connection = db.CreateConnection(); await connection.OpenAsync(ct);
            await using var command = new Npgsql.NpgsqlCommand("SELECT l.file_content FROM teacher_lessons l JOIN courses c ON c.id=l.course_id WHERE l.id=@id AND c.teacher_id=@teacher", connection);
            command.Parameters.AddWithValue("id", request.lessonId);
            command.Parameters.AddWithValue("teacher", int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!));
            var bytes = await command.ExecuteScalarAsync(ct);
            return bytes is byte[] content ? Results.Ok(content) : Results.NotFound();
        });
        group.MapPost("/SearchQuickAccessAsync", async (SearchQuickAccessAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(await new TeacherController(db).SearchQuickAccessAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.keyword)));
        group.MapPost("/ImportQuestionsToExamAsync", async (ImportQuestionsToExamAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(await new TeacherController(db).ImportQuestionsToExamAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId, request.courseId, request.questions)));
        group.MapPost("/AddQuestionsFromBankAsync", async (AddQuestionsFromBankAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(await new TeacherController(db).AddQuestionsFromBankAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId, request.courseId, request.questionIds)));
        group.MapPost("/GetCourseQuestionBank", (GetCourseQuestionBankRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetCourseQuestionBank(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId)));
        group.MapPost("/GetQuestionBankChapters", (GetQuestionBankChaptersRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetQuestionBankChapters(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId)));
        group.MapPost("/GetRandomQuestionsByCriteria", (GetRandomQuestionsByCriteriaRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(new TeacherController(db).GetRandomQuestionsByCriteria(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.courseId, request.criteria)));
        group.MapPost("/AddRandomQuestionsToExamAsync", async (AddRandomQuestionsToExamAsyncRequest request, ClaimsPrincipal principal, CourseGuardDbContext db) => Results.Ok(await new TeacherController(db).AddRandomQuestionsToExamAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!) ,request.examId, request.courseId, request.criteria)));
    }
    internal record UpsertTeacherProfileRequest(TeacherProfileModel input);
    internal record CreateCourseRequest(TeacherCourseModel input);
    internal record UpdateCourseRequest(TeacherCourseModel input);
    internal record SubmitCourseForApprovalRequest(int courseId);
    internal record DeleteCourseRequest(int courseId);
    internal record CreateLessonRequest(TeacherLessonModel input);
    internal record UpdateLessonRequest(TeacherLessonModel input);
    internal record DeleteLessonRequest(int lessonId);
    internal record CreateAssignmentRequest(TeacherAssignmentModel input);
    internal record UpdateAssignmentRequest(TeacherAssignmentModel input);
    internal record DeleteAssignmentRequest(int assignmentId);
    internal record CreateExamRequest(TeacherExamModel input);
    internal record UpdateExamRequest(TeacherExamModel input);
    internal record ActivateExamRequest(int examId);
    internal record CanActivateExamRequest(int examId);
    internal record DeleteExamRequest(int examId);
    internal record GetExamQuestionsRequest(int examId);
    internal record GetExamStatusRequest(int examId);
    internal record CreateExamQuestionRequest(TeacherExamQuestionModel input);
    internal record UpdateExamQuestionRequest(TeacherExamQuestionModel input);
    internal record DeleteExamQuestionRequest(int examId, int questionId);
    internal record GetEnrolledStudentsRequest(int? courseId);
    internal record ApproveEnrollmentRequest(int courseId, int studentId);
    internal record RejectEnrollmentRequest(int courseId, int studentId);
    internal record GetResultsRequest(int? courseId, int? examId);
    internal record UpdateScoreRequest(TeacherScoreModel input);
    internal record GetMaterialsRequest(int? courseId);
    internal record CreateMaterialRequest(TeacherMaterialModel input);
    internal record UpdateMaterialRequest(TeacherMaterialModel input);
    internal record DeleteMaterialRequest(int materialId);
    internal record GetAttendanceSummaryRequest(int sessionId);
    internal record CreateScheduleItemRequest(TeacherScheduleItemModel input);
    internal record UpdateScheduleItemRequest(TeacherScheduleItemModel input);
    internal record DeleteScheduleItemRequest(int scheduleId);
    internal record UpdateSessionStatusAsyncRequest(int sessionId, bool isOpened, string? meetingLink);
    internal record GetStudentSubmissionsAsyncRequest(int? courseId);
    internal record GetSubmissionContentAsyncRequest(int submissionId);
    internal record UpdateGradeAsyncRequest(int submissionId, decimal score, string feedback);
    internal record GetLessonFileContentAsyncRequest(int lessonId);
    internal record SearchQuickAccessAsyncRequest(string keyword);
    internal record ImportQuestionsToExamAsyncRequest(int examId, int courseId, List<TeacherExamQuestionModel> questions);
    internal record AddQuestionsFromBankAsyncRequest(int examId, int courseId, IReadOnlyList<int> questionIds);
    internal record GetCourseQuestionBankRequest(int courseId);
    internal record GetQuestionBankChaptersRequest(int courseId);
    internal record GetRandomQuestionsByCriteriaRequest(int courseId, IReadOnlyList<RandomQuestionCriteria> criteria);
    internal record AddRandomQuestionsToExamAsyncRequest(int examId, int courseId, IReadOnlyList<RandomQuestionCriteria> criteria);
}
